def isCI = System.getenv("CI") != null
def testLoggingConfig = ["skipped", "failed"]
def parallelism = Runtime.runtime.availableProcessors()

if (!isCI) {
    testLoggingConfig = ["failed"]
    parallelism = parallelism.intdiv(2) ?: 1
}

test {
    maxHeapSize = "1200m"
    maxParallelForks = parallelism
    timeout = Duration.ofMinutes(30)

    useJUnitPlatform()
}


tasks.register('testNG', Test) {
    description = 'Runs TestNG tests'
    group = 'verification'

    // Important: point to the same compiled test classes
    testClassesDirs = sourceSets.test.output.classesDirs
    classpath = sourceSets.test.runtimeClasspath

    // Tell it to use TestNG explicitly
    useTestNG()

    maxHeapSize = "1200m"
    maxParallelForks = parallelism
    timeout = Duration.ofMinutes(30)

    // Ensure JUnit-compatible XML output in the standard location
    reports {
        html.required = true
        junitXml.required = true
        junitXml.outputLocation = file("${buildDir}/test-results/test")   // ← important
    }

    // Optional: fine-tune includes/excludes
    // include '**/*NgTest.class', '**/*TestNG.class'
    // exclude '**/*JUnitTest.class'

    // Optional: reports, listeners, etc.
    testLogging {
        events = testLoggingConfig
        exceptionFormat = "full"

        debug.events = testLoggingConfig
        debug.exceptionFormat = "full"

        info.events = testLoggingConfig
        info.exceptionFormat = "full"

        warn.events = testLoggingConfig
        warn.exceptionFormat = "full"
    }
}

check.dependsOn testNG

tasks.withType(Test) {
    testLogging {
        events = testLoggingConfig
        exceptionFormat = "full"

        debug.events = testLoggingConfig
        debug.exceptionFormat = "full"

        info.events = testLoggingConfig
        info.exceptionFormat = "full"

        warn.events = testLoggingConfig
        warn.exceptionFormat = "full"
    }
}

if (experimental == null || "".equals(experimental)) {
    apply plugin: "jacoco"

    jacocoTestReport {
        dependsOn test
        dependsOn testNG

        reports {
            xml.required.set(true)
            csv.required.set(false)
            html.required.set(true)
        }
    }

    check.dependsOn jacocoTestReport
}


checkstyle {
    configFile = project.file("config/checkstyle/checkstyle.xml")
    configProperties = [
            "checkstyle.suppressions.file": project.file("config/checkstyle/suppressions.xml"),
            "checkstyle.header.file"      : project.file("config/license/HEADER_JAVA"),
            "project_loc"                 : project.projectDir.absolutePath
    ]
    checkstyleMain.exclude '**/module-info.java'
}

if (project.hasProperty("releaseMode")) {
    logger.lifecycle("ReleaseMode: {}", project.releaseMode)


  if ("full" == project.releaseMode) {
    signing {
      if (project.hasProperty("SIGNING_PRIVATE_KEY") && project.hasProperty("SIGNING_PASSWORD")) {
         useInMemoryPgpKeys(project.getProperty("SIGNING_PRIVATE_KEY"), project.getProperty("SIGNING_PASSWORD"))
         sign(publishing.publications)
      }
    }
  }
  mavenPublishing {
      // or when publishing to https://central.sonatype.com/
      publishToMavenCentral(true, com.vanniktech.maven.publish.DeploymentValidation.PUBLISHED)

      // signAllPublications()
  }
}

