14	package io.reactivex.rxjava4.internal.operators.streamable;
15	
16	import java.io.Serial;
17	import java.util.Collection;
18	import java.util.concurrent.*;
19	import java.util.concurrent.atomic.*;
20	import java.util.function.*;
21	
22	import io.reactivex.rxjava4.annotations.*;
23	import io.reactivex.rxjava4.core.*;
24	import io.reactivex.rxjava4.core.config.StreamableInterceptConfig;
25	import io.reactivex.rxjava4.disposables.Disposable;
26	import io.reactivex.rxjava4.exceptions.*;
27	import io.reactivex.rxjava4.functions.Consumer;
28	import io.reactivex.rxjava4.internal.util.*;
29	
30	/**
31	 * Helper static methods for {@link Streamable}s, {@link CompletableFuture}s and {@link CompletionStage}s.
32	 * @since 4.0.0
33	 */
34	public enum StreamableHelper {
35	    ;
36	
37	    /**
38	     * Checks which source completes first, calls the given acceptor with 1 or 2 indicating the winner,
39	     * then terminates the resulting {@link CompletableFuture} with said terminal event.
40	     * <p>
41	     * Use the {@code thenAcceptor} to do something about the winner and/or loser before the terminal
42	     * signal is propagated further.
43	     * @param <T> the common element type of the stages
44	     * @param first the first stage to wait for
45	     * @param second the second stage to wait for
46	     * @param thenAcceptor the callback that receives who won
47	     * @return the new {@code CompletableFuture} that gets completed with the winner's event.
48	     */
49	    @CheckReturnValue
50	    @NonNull
51	    public static <T> CompletableFuture<T> race(CompletionStage<T> first, CompletionStage<T> second, IntConsumer thenAcceptor) {
52	        var result = new CompletableFuture<T>();
53	        var winner = new AtomicInteger();
54	        first.whenComplete((v, e) -> {
55	            if (winner.compareAndSet(0, 1)) {
56	                thenAcceptor.accept(1);
57	                if (e != null) {
58	                    result.completeExceptionally(e);
59	                } else {
60	                    result.complete(v);
61	                }
62	            }
63	        });
64	        second.whenComplete((v, e) -> {
65	            if (winner.compareAndSet(0, 2)) {
66	                thenAcceptor.accept(2);
67	                if (e != null) {
68	                    result.completeExceptionally(e);
69	                } else {
70	                    result.complete(v);
71	                }
72	            }
73	        });
74	
75	        return result;
76	    }
77	
78	    /**
79	     * Checks which source completes first, calls the given acceptor with 1 or 2 indicating the winner.
80	     * <p>
81	     * Use the {@code thenAcceptor} to do something about the winner and/or loser.
82	     * @param <T> the common element type of the stages
83	     * @param first the first stage to wait for
84	     * @param second the second stage to wait for
85	     * @param thenAcceptor the callback that receives who won
86	     */
87	    @CheckReturnValue
88	    @NonNull
89	    public static <T> void whenEither(CompletionStage<T> first, CompletionStage<T> second, IntConsumer thenAcceptor) {
90	        var result = new CompletableFuture<T>();
91	        var winner = new AtomicInteger();
92	        first.whenComplete((v, e) -> {
93	            if (winner.compareAndSet(0, 1)) {
94	                thenAcceptor.accept(1);
95	                if (e != null) {
96	                    result.completeExceptionally(e);
97	                } else {
98	                    result.complete(v);
99	                }
100	            }
101	        });
102	        second.whenComplete((v, e) -> {
103	            if (winner.compareAndSet(0, 2)) {
104	                thenAcceptor.accept(2);
105	                if (e != null) {
106	                    result.completeExceptionally(e);
107	                } else {
108	                    result.complete(v);
109	                }
110	            }
111	        });
112	    }
113	
114	    /**
115	     * Creates a {@link CompletableFuture} that completes when both sources complete in a way,
116	     * relaying one or the other's exception, or both exceptions via {@link CompositeException}.
117	     * @param one a stage to wait for completion
118	     * @param two a stage to wait for completion
119	     * @return then new {@code CompletableFuture} instance
120	     */
121	    @CheckReturnValue
122	    @NonNull
123	    public static CompletableFuture<Void> whenBoth(CompletionStage<?> one, CompletionStage<?> two) {
124	        var result = new CompletableFuture<Void>();
125	        var errors = new AtomicThrowable();
126	        var wip = new AtomicInteger(2);
127	        BiConsumer<Object, Throwable> handler = (_, e) -> {
128	            if (e != null) {
129	                errors.tryAddThrowableOrReport(e);
130	            }
131	            if (wip.decrementAndGet() == 0) {
132	                var err = errors.get();
133	                if (err != null) {
134	                    result.completeExceptionally(err);
135	                } else {
136	                    result.complete(null);
137	                }
138	            }
139	        };
140	        one.whenComplete(handler);
141	        two.whenComplete(handler);
142	        return result;
143	    }
144	
145	    /**
146	     * Creates a {@link CompletableFuture} that completes when the second completes after the first completes,
147	     * chaining their completion into a sequence and relays either or both's exception as is or via a
148	     * {@link CompositeException}.
149	     * @param first the first stage to wait for completion
150	     * @param supplier produces the next stage when the first stage completes in any way
151	     * @return the new {@code CompletableFuture} instance
152	     */
153	    @CheckReturnValue
154	    @NonNull
155	    public static CompletableFuture<Void> andThenSupply(@NonNull CompletionStage<?> first,
156	            @NonNull Supplier<@NonNull ? extends CompletionStage<?>> supplier) {
157	        var result = new CompletableFuture<Void>();
158	        var errors = new AtomicThrowable();
159	        first.whenComplete((_, e) -> {
160	            if (e != null) {
161	                errors.tryAddThrowableOrReport(e);
162	            }
163	            supplier.get().whenComplete((_, e1) -> {
164	                if (e1 != null) {
165	                    errors.tryAddThrowableOrReport(e1);
166	                }
167	                var err = errors.get();
168	                if (err != null) {
169	                    result.completeExceptionally(err);
170	                } else {
171	                    result.complete(null);
172	                }
173	            });
174	        });
175	        return result;
176	    }
177	
178	    /**
179	     * Check if the throwable is itself a {@link CancellationException} or
180	     * it is a {@link CompletionException} caused by a {@code CancellationException}.
181	     * <p>
182	     * Why is that {@code completableFuture.completeExceptionally(new CancellationException())}
183	     * results in the wrapping? no idea.
184	     * @param e the throwable to check
185	     * @return true if the throwable holds a cancellation exception in some fashion
186	     */
187	    @CheckReturnValue
188	    static boolean isCancellation(@Nullable Throwable e) {
189	        return e instanceof CancellationException
190	                || (e instanceof CompletionException && e.getCause() instanceof CancellationException);
191	    }
192	
193	    /**
194	     * Creates a {@link CompletableFuture} that relays the terminal events of the source {@code stage}
195	     * except any {@link CancellationException} if the given {@link Disposable#isDisposed()} returns {@code true}.
196	     * <p>
197	     * Use it to suppress expected cancellation errors.
198	     * @param <T> the element type of the stage
199	     * @param stage the original stage to gate the cancellation exception of
200	     * @param disposable the {@code Disposable} to check
201	     * @param defaultValue to signal if the cancellation exception was gated
202	     * @return the new {@code CompletableFuture} instance
203	     */
204	    @CheckReturnValue
205	    @NonNull
206	    public static <T> CompletableFuture<T> suppressCancel(
207	            @NonNull CompletionStage<T> stage, @NonNull Disposable disposable, T defaultValue) {
208	        var result = new CompletableFuture<T>();
209	        stage.whenComplete((v, e) -> {
210	            if (disposable.isDisposed() && isCancellation(e)) {
211	                result.complete(defaultValue);
212	            } else
213	            if (e != null) {
214	                result.completeExceptionally(e);
215	            } else {
216	                result.complete(v);
217	            }
218	        });
219	        return result;
220	    }
221	
222	    /**
223	     * Creates a {@link CompletableFuture} that suppresses the source value or cancellation exception and
224	     * replaces them with a normal completion signaling the {@code defaultValue}.
225	     * <p>
226	     * Use it to suppress expected cancellation errors and any source value.
227	     * @param <T> the element type of the stage
228	     * @param stage the original stage to gate the cancellation exception of
229	     * @param defaultValue to signal if the cancellation exception was gated
230	     * @return the new {@code CompletableFuture} instance
231	     */
232	    @CheckReturnValue
233	    @NonNull
234	    public static <T> CompletableFuture<T> suppressValueAndCancel(
235	            @NonNull CompletionStage<T> stage, T defaultValue) {
236	        var result = new CompletableFuture<T>();
237	        stage.whenComplete((_, e) -> {
238	            if (isCancellation(e)) { // FIXME coverage possible even?
239	                result.complete(defaultValue);
240	            } else
241	            if (e != null) {
242	                result.completeExceptionally(e);
243	            } else {
244	                result.complete(defaultValue);
245	            }
246	        });
247	        return result;
248	    }
249	
250	    /**
251	     * When the stage completes, the future is completed with the very same value or exception.
252	     * @param <T> the element type
253	     * @param stage the stage to forward its completion signals
254	     * @param future the future to receive the completion signals
255	     */
256	    public static <T> void forward(CompletionStage<T> stage, CompletableFuture<T> future) {
257	        stage.whenComplete((u, e) -> {
258	            if (e != null) {
259	                future.completeExceptionally(e);
260	            } else {
261	                future.complete(u);
262	            }
263	        });
264	    }
265	
266	    /**
267	     * Awaits all the stages to complete in any form, then completes the returned {@link CompletableFuture} normally,
268	     * or via the possible {@link CompositeException}s of all the failed stages.
269	     * @param stages the collection of {@link CompletionStage}s to await
270	     * @return the new {@code CompletableFuture} that gets completed
271	     */
272	    public static CompletableFuture<Void> awaitAllVoid(Collection<? extends CompletionStage<?>> stages) {
273	        int size = stages.size();
274	        if (size == 0) {
275	            return Streamer.FINISHED;
276	        }
277	        var cf = new CompletableFuture<Void>();
278	        var wip = new AtomicIntegerCompleter(cf, size);
279	
280	        for (var stage : stages) {
281	            stage.whenComplete(wip);
282	        }
283	
284	        return cf;
285	    }
286	
287	    public static CompletableFuture<Boolean> awaitAllBoolean(Collection<? extends CompletionStage<Boolean>> stages) {
288	        int size = stages.size();
289	        if (size == 0) {
290	            return Streamer.NEXT_FALSE;
291	        }
292	        var cf = new CompletableFuture<Boolean>();
293	        var wip = new AtomicIntegerBooleanCompleter(cf, size);
294	
295	        for (var stage : stages) {
296	            stage.whenComplete(wip);
